320:   obtenerNumeroDisponibilidad(vigencia: string) {
321:     this.isLoading = true;
322:     this.cdps = [];
323:     this.form.get('cdp')?.reset();
324: 
325:     this.cdpsService
326:       .get(
327:         `cdps/numeros-disponibilidad?vigencia=${vigencia}&unidadEjecutora=${this.unidadEjecutora}`
328:       )
329:       .pipe(
330:         takeUntil(this.destroy$),
331:         finalize(() => {
332:           this.isLoading = false;
333:           this.cdRef.detectChanges();
334:         })
335:       )
336:       .subscribe({
337:         next: (response: any) => {
338:           if (response.Status === 200) {
339:             const uniqueCDPs = new Map<string, CDPData>();
340: 
341:             response.Data.forEach((cdp: CDPData) => {
342:               if (
343:                 cdp.estadocdp !== 'AGOTADO' &&
344:                 !uniqueCDPs.has(cdp.numero_disponibilidad)
345:               ) {
346:                 uniqueCDPs.set(cdp.numero_disponibilidad, cdp);
347:               }
348:             });
349: 
350:             this.cdps = Array.from(uniqueCDPs.values()).map((cdp) => ({
351:               Id: cdp.numero_disponibilidad,
352:               Nombre: cdp.numero_disponibilidad,
353:             }));
354: 
355:             this.sortCDPs();
356: 
357:           } else {
358:             console.error('Error loading CDPs:', response.Message);
359:           }
360:         },
361:         error: (error) => {
362:           console.error('Error loading CDPs:', error);
363:         },
364:       });
365:   }
