367:   obtenerCDP(vigencia: string, numeroDisponibilidad: string) {
368:     this.isLoading = true;
369:     this.cdpsService
370:       .get(
371:         `cdps?vigencia=${vigencia}&unidadEjecutora=${this.unidadEjecutora}&numeroDisponibilidad=${numeroDisponibilidad}`
372:       )
373:       .pipe(
374:         takeUntil(this.destroy$),
375:         finalize(() => {
376:           this.isLoading = false;
377:           this.cdRef.detectChanges();
378:         })
379:       )
380:       .subscribe({
381:         next: (response: any) => {
382:           if (response.Status === 200) {
383:             const newCDP = response.Data[0]; //La respuesta puede retornar varias veces el mismo CDP
384:             this.selectedCDP = [...this.selectedCDP, newCDP];
385:             this.updateValorAcumulado();
386:             this.removeSelectedCDPsFromList();
387:             this.form.get('cdp')?.reset();
388:           } else {
389:             console.error('Error loading row data:', response.Message);
390:           }
391:         },
392:         error: (error) => {
393:           console.error('Error loading row data:', error);
394:         },
395:       });
396:   }
397: 
398:   removeSelectedCDPsFromList() {
399:     this.cdps = this.cdps.filter(
400:       (cdp) =>
401:         !this.selectedCDP.some(
402:           (selected) => selected.numero_disponibilidad === cdp.Id
403:         )
404:     );
405:   }
