423:         (cdp) => ({
424:           numero_cdp_id: parseInt(cdp.numero_disponibilidad),
425:           fecha_registro: new Date(),
426:           vigencia_cdp: parseInt(cdp.vigencia),
427:           contrato_general_id: this.contratoGeneralId,
428:         })
429:       );
430: 
